            return handle;
        }
    }

    internal static ProjLibProjectedCurve? FromNative(nint nativeHandle, string operation) =>
        nativeHandle == 0 ? null : new ProjLibProjectedCurve(CreateHandle(nativeHandle, operation));

    private static ProjLibProjectedCurveHandle CreateHandle(nint nativeHandle, string operation)
    {
        if (nativeHandle == 0) throw new OcctException("UnknownException", $"Native operation '{operation}' returned a null generated shared handle.");
        return new ProjLibProjectedCurveHandle(nativeHandle);
    }
}
